280	function formatZodError(error: z.ZodError, context: string): string {
281	  const issues = error.issues
282	    .map((i) => {
283	      // Handle union errors specifically to give better context
284	      if (i.code === z.ZodIssueCode.invalid_union) {
285	        return i.unionErrors
286	          .map((unionError, index) => {
287	            const label =
288	              agentUnionOptions[index]?.label ?? `Agent type #${index + 1}`;
289	            const unionIssues = unionError.issues
290	              .map((u) => `${u.path.join('.')}: ${u.message}`)
291	              .join(', ');
292	            return `(${label}) ${unionIssues}`;
293	          })
294	          .join('\n');
295	      }
296	      return `${i.path.join('.')}: ${i.message}`;
297	    })
298	    .join('\n');
299	  return `${context}:\n${issues}`;
300	}
